// PreToolUse (Bash and PowerShell): keeps real process data (ZIPs, PDFs,
// processing outputs, the benchmark corpus) out of git. The event's tool_name
// picks the syntax the command is read with.
import { execFileSync } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { executar, normalizar, RAIZ } from './lib.mjs';

// .txt, .log and .jsonl files are processing outputs, logs or telemetry unless
// they live in harness/doc folders.
const TXT_PERMITIDO = /^(docs|scripts|\.claude)\//;
// Synthetic, fictitious fixtures generated by scripts/bench/gerar.
const FIXTURES = 'scripts/bench/fixtures/';

// raiz is the root of the checkout the path is relative to (a worktree when the
// candidates came from one), so a bench dir inside that checkout also matches.
export function arquivoSensivel(caminho, benchDir, raiz = RAIZ) {
  const n = normalizar(caminho, raiz);
  if (!n || n === '.' || n.startsWith(FIXTURES)) return false;
  if (benchDir) {
    const b = normalizar(benchDir, raiz).replace(/\/$/, '');
    if (n === b || n.startsWith(b + '/')) return true;
  }
  if (/\.(zip|pdf)$/.test(n)) return true;
  // Logs and telemetry (.log, .jsonl) may hold real process data too.
  if (/\.(txt|log|jsonl)$/.test(n) && !TXT_PERMITIDO.test(n)) return true;
  return false;
}

// comandos splits a shell command line into simple commands (arrays of words),
// honouring quotes and treating newline ; & && || | ( ) as separators.
export function comandos(linha) {
  return comandosESubshells(linha).filter(Array.isArray);
}

// comandosESubshells is comandos plus the strings '(' and ')' where a subshell
// opens and closes, so a `cd` inside one can be undone when it ends.
function comandosESubshells(linha) {
  const lista = [];
  let atual = [];
  let palavra = null;
  const fecharPalavra = () => {
    if (palavra !== null) atual.push(palavra);
    palavra = null;
  };
  const fecharComando = () => {
    fecharPalavra();
    if (atual.length) lista.push(atual);
    atual = [];
  };
  for (let i = 0; i < linha.length; i++) {
    const c = linha[i];
    if (c === '"' || c === "'") {
      const fim = linha.indexOf(c, i + 1);
      const trecho = fim < 0 ? linha.slice(i + 1) : linha.slice(i + 1, fim);
      palavra = (palavra ?? '') + trecho;
      i = fim < 0 ? linha.length : fim;
    } else if (/[\n;&|()]/.test(c)) {
      fecharComando();
      if (c === '(' || c === ')') lista.push(c);
    } else if (/\s/.test(c)) {
      fecharPalavra();
    } else {
      palavra = (palavra ?? '') + c;
    }
  }
  fecharComando();
  return lista;
}

// comandosPowerShell splits a PowerShell command line into simple commands.
// Quotes: '...' with '' for a literal quote; "..." with `x and "" as escapes.
// Outside quotes ` escapes the next character (` + newline continues the line),
// # at the start of a word comments out the rest of the line, a comma separates
// array items (a native command gets each as its own argument), and newline
// ; & | ( ) { } separate commands. Parentheses are not subshells: a cd inside
// them persists. Words with $ (outside single quotes) or starting with @ are
// computed at run time; each command lists them in its .dinamicas Set.
export function comandosPowerShell(linha) {
  const lista = [];
  let atual = [];
  let dinamicas = new Set();
  let palavra = null;
  let dinamica = false;
  // ( or { after the command started: its arguments hold an expression.
  let expressao = false;
  const fecharPalavra = () => {
    if (palavra !== null) {
      atual.push(palavra);
      if (dinamica) dinamicas.add(palavra);
    }
    palavra = null;
    dinamica = false;
  };
  const fecharComando = () => {
    fecharPalavra();
    if (atual.length) lista.push(Object.assign(atual, { dinamicas, expressao }));
    atual = [];
    dinamicas = new Set();
    expressao = false;
  };
  for (let i = 0; i < linha.length; i++) {
    const c = linha[i];
    if (c === "'") {
      let trecho = '';
      let j = i + 1;
      for (; j < linha.length; j++) {
        if (linha[j] === "'") {
          if (linha[j + 1] === "'") { trecho += "'"; j++; continue; }
          break;
        }
        trecho += linha[j];
      }
      palavra = (palavra ?? '') + trecho;
      i = j;
    } else if (c === '"') {
      let trecho = '';
      let j = i + 1;
      for (; j < linha.length; j++) {
        const d = linha[j];
        if (d === '`' && j + 1 < linha.length) { trecho += linha[++j]; continue; }
        if (d === '"') {
          if (linha[j + 1] === '"') { trecho += '"'; j++; continue; }
          break;
        }
        if (d === '$') dinamica = true;
        trecho += d;
      }
      palavra = (palavra ?? '') + trecho;
      i = j;
    } else if (c === '`') {
      i++;
      const d = linha[i];
      if (d === undefined) continue;
      if (d === '\n' || d === '\r') {
        if (d === '\r' && linha[i + 1] === '\n') i++;
        fecharPalavra();
        continue;
      }
      palavra = (palavra ?? '') + d;
    } else if (c === '#' && palavra === null) {
      while (i + 1 < linha.length && linha[i + 1] !== '\n') i++;
    } else if (/[\n;&|(){}]/.test(c)) {
      if ((c === '(' || c === '{') && (palavra !== null || atual.length)) expressao = true;
      fecharComando();
    } else if (c === ','|| /\s/.test(c)) {
      fecharPalavra();
    } else {
      if (c === '$' || (c === '@' && palavra === null)) dinamica = true;
      palavra = (palavra ?? '') + c;
    }
  }
  fecharComando();
  return lista;
}

// Location cmdlets and their aliases (PowerShell is case-insensitive).
const CD_PS = new Set(['cd', 'chdir', 'sl', 'set-location', 'pushd', 'push-location']);
const PUSHD_PS = new Set(['pushd', 'push-location']);
const POPD_PS = new Set(['popd', 'pop-location']);

// destinoCdPowerShell is where Set-Location/Push-Location (or an alias) lands,
// or null when the hook cannot know: no target, a computed one ($x, or a
// parenthesised expression the tokenizer dropped), - and + (history), or a
// relative target from an already unknown dir.
function destinoCdPowerShell(palavras, dir) {
  const args = palavras.slice(1);
  let alvo;
  for (let k = 0; k < args.length; k++) {
    const a = args[k];
    const m = a.match(/^-(path|literalpath|pspath|lp)(?::(.*))?$/i);
    if (m) { alvo = m[2] ? m[2] : args[k + 1]; break; }
    if (/^-stackname$/i.test(a)) { k++; continue; }
    if (a.startsWith('-') && a !== '-') continue;
    alvo = a;
    break;
  }
  if (alvo === undefined || alvo === '-' || alvo === '+' || palavras.dinamicas?.has(alvo)) return null;
  if (alvo === '~' || /^~[\\/]/.test(alvo)) alvo = os.homedir() + alvo.slice(1);
  const destino = caminhoWindows(alvo);
  if (path.isAbsolute(destino)) return path.resolve(destino);
  return dir === null ? null : path.resolve(caminhoWindows(dir), destino);
}

// The git executable in any case, with or without a folder and .exe (Windows
// finds GIT, Git.exe and C:/Git/cmd/git.exe alike).
const EH_GIT = /^(.*[\\/])?git(\.exe)?$/i;
// Global options whose value is the next word.
const GLOBAIS_COM_VALOR = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--config-env', '--super-prefix', '--attr-source']);

// subcomandoGit returns { sub, args, dirC, outraArvore } for a git invocation,
// skipping global options (dirC lists the -C dirs; outraArvore is set by
// --git-dir/--work-tree, whose checkout the hook does not list). `stage` is `add`.
function subcomandoGit(palavras) {
  const i = palavras.findIndex((p) => EH_GIT.test(p));
  if (i < 0) return null;
  let j = i + 1;
  const dirC = [];
  let outraArvore = false;
  while (j < palavras.length && palavras[j].startsWith('-')) {
    const a = palavras[j];
    if (a === '-C') dirC.push(palavras[j + 1]);
    if (/^--(git-dir|work-tree)(=|$)/.test(a)) outraArvore = true;
    if (GLOBAIS_COM_VALOR.has(a)) j++;
    j++;
  }
  const sub = palavras[j] === 'stage' ? 'add' : palavras[j];
  return { sub, args: palavras.slice(j + 1), dirC, outraArvore };
}

// Commands that run a command line held in a string or read from stdin. The
// hook does not parse the inner line: if it mentions git with add, stage or
// commit, it blocks (fails closed); `bash -c "git status"` passes.
const EMBRULHOS = new Set(['iex', 'invoke-expression', 'cmd', 'bash', 'sh', 'zsh', 'pwsh', 'powershell', 'eval',
  'xargs', 'start-process', 'saps', 'start', 'wsl', 'invoke-command', 'icm']);

function embrulhaGitQueGrava(palavras) {
  const nome = String(palavras[0] ?? '').replace(/^.*[\\/]/, '').replace(/\.exe$/i, '').toLowerCase();
  if (!EMBRULHOS.has(nome)) return false;
  const resto = palavras.slice(1).join(' ');
  return /\bgit(\.exe)?\b/i.test(resto) && /\b(add|stage|commit)\b/.test(resto);
}

// Git Bash style /c/Users/... becomes c:/Users/... before path.resolve.
const caminhoWindows = (p) => String(p).replace(/^\/([a-z])(\/|$)/i, (_, d) => `${d.toUpperCase()}:/`);
const resolverDir = (base, alvo) => (alvo ? path.resolve(caminhoWindows(base), caminhoWindows(alvo)) : base);

// Shell words that may precede a command (`{ cd x; ...}`, `if cd x; then ...`).
const PALAVRAS_CHAVE = new Set(['{', 'if', 'then', 'do', 'else', 'elif', 'while', 'until', '!']);

// destinoCd is where `cd`/`pushd` with these arguments lands, skipping -L, -P,
// -e, -@ and `--`. With no target or `-` (home, previous dir: unknown here) it
// returns the event's cwd, whose checkout listing is the closest safe guess.
function destinoCd(args, dir, inicio) {
  let k = 0;
  while (k < args.length && /^-[LPe@]+$/.test(args[k])) k++;
  if (args[k] === '--') k++;
  const alvo = args[k];
  if (!alvo || alvo === '-') return inicio;
  return resolverDir(dir, alvo);
}

// dirGitPowerShell applies `git -C` dirs to dir; null when any is computed or
// relative to an unknown dir.
function dirGitPowerShell(dirC, dir, dinamicas) {
  let atual = dir;
  for (const c of dirC) {
    if (!c) continue;
    if (dinamicas.has(c)) return null;
    const destino = caminhoWindows(c);
    if (path.isAbsolute(destino)) atual = path.resolve(destino);
    else if (atual !== null) atual = path.resolve(caminhoWindows(atual), destino);
  }
  return atual;
}

// opcoesComValor are commit options whose next word is a value, not a path.
const OPCOES_COM_VALOR = new Set(['-m', '--message', '-F', '--file', '-C', '-c', '--author', '--date', '-t', '--template', '--fixup', '--squash']);

function caminhosDeArgs(args) {
  const caminhos = [];
  for (let k = 0; k < args.length; k++) {
    const a = args[k];
    if (a === '--') continue;
    if (OPCOES_COM_VALOR.has(a)) { k++; continue; }
    if (a.startsWith('-')) continue;
    caminhos.push(a);
  }
  return caminhos;
}

// amplo: a pathspec that can match many files (., ./, dirs, globs).
const amplo = (a) => a === '.' || a === './' || a === ':/' || a.endsWith('/') || /[*?[]/.test(a);

export function avaliar(evento, ctx = {}) {
  const cmd = evento?.tool_input?.command;
  if (typeof cmd !== 'string' || !/\bgit\b/i.test(cmd)) return { codigo: 0 };
  const benchDir = ctx.benchDir ?? process.env.EPROCIA_BENCH_DIR;
  const listar = ctx.listar ?? listarCandidatos;
  // Broad pathspecs expand in the command's checkout (a worktree, say), not in
  // the one holding this hook ($CLAUDE_PROJECT_DIR): start at the event's cwd
  // and follow `cd` and `git -C` (f5b7a48 slipped .txt files in otherwise).
  const inicio = typeof evento.cwd === 'string' && evento.cwd ? evento.cwd : RAIZ;
  // PowerShell tool: its own syntax; dir becomes null when a cd goes somewhere
  // the hook cannot resolve, and a broad add/commit from there is blocked.
  const powershell = evento?.tool_name === 'PowerShell';
  let dir = inicio;
  const subshells = []; // dir to restore when each open subshell closes
  const pushd = [];

  // Limitation: the `)` of a case pattern inside a subshell is read as closing
  // the subshell, so a later cd may be undone too early.
  for (const item of powershell ? comandosPowerShell(cmd) : comandosESubshells(cmd)) {
    if (item === '(') { subshells.push(dir); continue; }
    if (item === ')') { if (subshells.length) dir = subshells.pop(); continue; }
    let p = 0;
    while (p < item.length && PALAVRAS_CHAVE.has(item[p])) p++;
    const palavras = Object.assign(item.slice(p), { dinamicas: item.dinamicas ?? new Set() });
    if (powershell) {
      const nome = String(palavras[0]).toLowerCase();
      if (CD_PS.has(nome)) {
        if (PUSHD_PS.has(nome)) pushd.push(dir);
        dir = destinoCdPowerShell(palavras, dir);
        continue;
      }
      if (POPD_PS.has(nome)) { if (pushd.length) dir = pushd.pop(); continue; }
    } else {
      if (palavras[0] === 'cd' || palavras[0] === 'pushd') {
        if (palavras[0] === 'pushd') pushd.push(dir);
        dir = destinoCd(palavras.slice(1), dir, inicio);
        continue;
      }
      if (palavras[0] === 'popd') { if (pushd.length) dir = pushd.pop(); continue; }
    }
    if (embrulhaGitQueGrava(palavras)) {
      return { codigo: 2, stderr: `Bloqueado: \`git add\`/\`commit\` dentro de outro comando (${palavras[0]}); o hook não lê a linha de dentro. Rode o git direto, com os arquivos pelo nome.` };
    }
    const g = subcomandoGit(palavras);
    if (!g || (g.sub !== 'add' && g.sub !== 'commit')) continue;

    if (g.args.some((a) => a.startsWith('--pathspec-from-file'))) {
      return { codigo: 2, stderr: `Bloqueado: \`git ${g.sub} --pathspec-from-file\` lê os caminhos de um arquivo que o hook não confere. Adicione os arquivos pelo nome.` };
    }
    let caminhos = caminhosDeArgs(g.args);
    if (powershell) {
      // ( or { in the middle of the git command: an expression whose value the
      // hook cannot know (git add ('x.pdf'), git add {x.pdf}).
      if (item.expressao) {
        return { codigo: 2, stderr: `Bloqueado: \`git ${g.sub}\` com argumento calculado (expressão entre parênteses ou chaves); o hook não sabe que arquivos são. Adicione os arquivos pelo nome.` };
      }
      const calculados = caminhos.filter((a) => palavras.dinamicas.has(a) || a.startsWith('@'));
      if (calculados.length) {
        return { codigo: 2, stderr: `Bloqueado: \`git ${g.sub}\` com argumento calculado (${calculados.join(', ')}); o hook não sabe que arquivos são. Adicione os arquivos pelo nome.` };
      }
      // .\x and dir\ read like ./x and dir/ (amplo, normalizar).
      caminhos = caminhos.map((a) => a.replace(/\\/g, '/'));
    }
    const diretos = caminhos.filter((a) => !amplo(a) && arquivoSensivel(a, benchDir));
    if (diretos.length) {
      return { codigo: 2, stderr: `Bloqueado: dados reais não entram no git (${diretos.join(', ')}). Adicione ao .gitignore se for saída local.` };
    }

    const todos = g.args.some((a) => a === '-A' || a === '--all' || a === '-u' || a === '--update' || a === '--no-ignore-removal')
      || (g.sub === 'add' && g.args.some((a) => /^-[a-zA-Z]*[Au][a-zA-Z]*$/.test(a)))
      || (g.sub === 'commit' && g.args.some((a) => /^-[a-zA-Z]*a[a-zA-Z]*$/.test(a) || a === '--all'));
    const pathspecs = todos ? [] : caminhos.filter(amplo);
    // Plain directory names (e.g. "git add internal") are also expanded by git.
    const outros = todos ? [] : caminhos.filter((a) => !amplo(a) && !/\.[a-z0-9]+$/i.test(a));
    if (!todos && !pathspecs.length && !outros.length) continue;

    const dirGit = g.outraArvore ? null
      : powershell ? dirGitPowerShell(g.dirC, dir, palavras.dinamicas) : g.dirC.reduce(resolverDir, dir);
    if (dirGit === null) {
      return { codigo: 2, stderr: `Bloqueado: não sei em que pasta \`git ${g.sub}\` roda (cd ou -C para um caminho calculado, histórico ou desconhecido, ou --work-tree/--git-dir), então não consigo listar o que ele incluiria. Use um caminho literal ou adicione os arquivos pelo nome.` };
    }
    const candidatos = listar(todos ? [] : [...pathspecs, ...outros], dirGit);
    if (candidatos === null) {
      return { codigo: 2, stderr: `Bloqueado: não consegui listar o que \`git ${g.sub}\` incluiria (git status falhou ou demorou). Adicione os arquivos pelo nome.` };
    }
    const ruins = candidatos.filter((a) => arquivoSensivel(a, benchDir, candidatos.raiz ?? RAIZ));
    if (ruins.length) {
      return { codigo: 2, stderr: `Bloqueado: \`git ${g.sub}\` amplo incluiria dados reais: ${ruins.slice(0, 5).join(', ')}. Adicione arquivos pelo nome ou ignore-os.` };
    }
  }
  return { codigo: 0 };
}

// listarCandidatos returns modified and untracked, non-ignored paths matching
// the pathspecs (all when empty) in dir, as paths from that checkout's root
// (--full-name), or null when git cannot answer in time. The array carries that
// root in .raiz, so arquivoSensivel can place a bench dir inside a worktree.
// Both git calls share one 3 s deadline: the hook itself has 5 s, and a hook
// killed by its timeout lets the command through.
const PRAZO_LISTAGEM_MS = 3000;

export function listarCandidatos(pathspecs, dir = RAIZ, { exec = execFileSync, agora = Date.now } = {}) {
  try {
    const fim = agora() + PRAZO_LISTAGEM_MS;
    const git = (args) => {
      const resta = fim - agora();
      if (resta <= 0) throw new Error('prazo esgotado');
      return exec('git', args, { cwd: dir, encoding: 'utf8', timeout: resta, stdio: ['ignore', 'pipe', 'ignore'] });
    };
    const raiz = git(['rev-parse', '--show-toplevel']).trim();
    const todos = pathspecs.length ? [] : [':/'];
    const saida = git(['ls-files', '-z', '-o', '-m', '--exclude-standard', '--full-name', '--', ...pathspecs, ...todos]);
    return Object.assign(saida.split('\0').filter(Boolean), { raiz });
  } catch {
    return null;
  }
}

await executar(import.meta.url, 'PreToolUse', avaliar);
